// src/services/websocket.js
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import mockBackend from './MockBackend';

class WebSocketService {
  constructor() {
    this.client = null;
    this.roomId = null;
    this.userId = null;
    this.callbacks = {};
    this.isMockMode = false;
  }

  connect(roomId, userId, username, callbacks) {
    this.roomId = roomId;
    this.userId = userId;
    this.callbacks = callbacks;

    // Check if we should use mock mode (no backend)
    const useMock = localStorage.getItem('useMockMode') === 'true';
    
    if (useMock) {
      this.isMockMode = true;
      this.connectMock(roomId, userId, username, callbacks);
      return;
    }

    const wsUrl = process.env.REACT_APP_WS_URL || 'http://localhost:8080';
    
    this.client = new Client({
      webSocketFactory: () => new SockJS(`${wsUrl}/ws`),
      debug: (str) => {
        console.log('STOMP:', str);
      },
      reconnectDelay: 5000,
      heartbeatIncoming: 4000,
      heartbeatOutgoing: 4000,
      onConnect: () => {
        console.log('Connected to WebSocket');
        
        this.client.subscribe(`/topic/room/${roomId}/play`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onPlay && callbacks.onPlay(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/pause`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onPause && callbacks.onPause(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/seek`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onSeek && callbacks.onSeek(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/change_video`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onVideoChange && callbacks.onVideoChange(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/user_joined`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onUserJoined && callbacks.onUserJoined(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/user_left`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onUserLeft && callbacks.onUserLeft(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/role_assigned`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onRoleAssigned && callbacks.onRoleAssigned(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/participant_removed`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onParticipantRemoved && callbacks.onParticipantRemoved(data);
        });
        
        this.client.subscribe(`/topic/room/${roomId}/chat`, (msg) => {
          const data = JSON.parse(msg.body);
          callbacks.onChat && callbacks.onChat(data);
        });
        
        this.client.publish({
          destination: '/app/join_room',
          body: JSON.stringify({ roomId, username, userId })
        });
      },
      onStompError: (frame) => {
        console.error('STOMP error:', frame);
        callbacks.onError && callbacks.onError(frame.headers.message);
      },
      onWebSocketError: (error) => {
        console.error('WebSocket error:', error);
        callbacks.onError && callbacks.onError('Connection error');
      }
    });
    
    this.client.activate();
  }

  connectMock(roomId, userId, username, callbacks) {
    console.log('Mock Mode: Connecting to room', roomId);
    
    // Check if room exists
    let room = mockBackend.getRoom(roomId);
    
    if (!room) {
      // Create room if it doesn't exist (for host)
      room = mockBackend.createRoom(roomId, userId, username);
      callbacks.onRoleAssigned && callbacks.onRoleAssigned({ userId, role: 'HOST' });
    } else {
      // Join existing room
      const result = mockBackend.joinRoom(roomId, userId, username);
      if (result) {
        callbacks.onRoleAssigned && callbacks.onRoleAssigned({ userId, role: result.role });
        // Send initial state
        callbacks.onVideoChange && callbacks.onVideoChange({ videoId: result.state.videoId });
        if (result.state.isPlaying) {
          callbacks.onPlay && callbacks.onPlay({ currentTime: result.state.currentTime });
        }
      }
    }
    
    // Subscribe to room events
    const unsubscribe = mockBackend.subscribe(roomId, (eventType, payload) => {
      switch(eventType) {
        case 'play':
          callbacks.onPlay && callbacks.onPlay(payload);
          break;
        case 'pause':
          callbacks.onPause && callbacks.onPause(payload);
          break;
        case 'seek':
          callbacks.onSeek && callbacks.onSeek(payload);
          break;
        case 'change_video':
          callbacks.onVideoChange && callbacks.onVideoChange(payload);
          break;
        case 'user_joined':
          callbacks.onUserJoined && callbacks.onUserJoined(payload);
          break;
        case 'user_left':
          callbacks.onUserLeft && callbacks.onUserLeft(payload);
          break;
        case 'role_assigned':
          callbacks.onRoleAssigned && callbacks.onRoleAssigned(payload);
          break;
        case 'participant_removed':
          callbacks.onParticipantRemoved && callbacks.onParticipantRemoved(payload);
          break;
        case 'chat':
          callbacks.onChat && callbacks.onChat(payload);
          break;
      }
    });
    
    // Store unsubscribe function
    this.unsubscribe = unsubscribe;
    
    // Get current participants
    const participants = mockBackend.getParticipants(roomId);
    participants.forEach(p => {
      if (p.userId !== userId) {
        callbacks.onUserJoined && callbacks.onUserJoined(p);
      }
    });
  }

  sendPlay(roomId, userId) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'play',
        payload: {},
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/play',
        body: JSON.stringify({ roomId, userId })
      });
    }
  }

  sendPause(roomId, userId) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'pause',
        payload: {},
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/pause',
        body: JSON.stringify({ roomId, userId })
      });
    }
  }

  sendSeek(roomId, userId, time) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'seek',
        payload: { time },
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/seek',
        body: JSON.stringify({ roomId, userId, time })
      });
    }
  }

  sendChangeVideo(roomId, userId, videoId) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'change_video',
        payload: { videoId },
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/change_video',
        body: JSON.stringify({ roomId, userId, videoId })
      });
    }
  }

  sendAssignRole(roomId, userId, targetId, role) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'assign_role',
        payload: { targetId, role },
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/assign_role',
        body: JSON.stringify({ roomId, userId, targetId, role })
      });
    }
  }

  sendRemoveParticipant(roomId, userId, targetId) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'remove_participant',
        payload: { targetId },
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/remove_participant',
        body: JSON.stringify({ roomId, userId, targetId })
      });
    }
  }

  sendChat(roomId, userId, username, message) {
    if (this.isMockMode) {
      mockBackend.handleRoomEvent({
        roomId,
        eventType: 'chat',
        payload: { username, message },
        senderId: userId
      });
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/chat',
        body: JSON.stringify({ roomId, userId, username, message })
      });
    }
  }

  disconnect() {
    if (this.isMockMode) {
      if (this.unsubscribe) {
        this.unsubscribe();
      }
      // Send leave event
      if (this.roomId && this.userId) {
        mockBackend.handleRoomEvent({
          roomId: this.roomId,
          eventType: 'leave_room',
          payload: {},
          senderId: this.userId
        });
      }
    } else if (this.client && this.client.connected) {
      this.client.publish({
        destination: '/app/leave_room',
        body: JSON.stringify({ roomId: this.roomId, userId: this.userId })
      });
      this.client.deactivate();
    }
  }
}

export default WebSocketService;
